import json

output = [[1]*12 for _ in range(29)]

# Input shape
output[20] = [1,1,4,4,1,4,4,4,1,1,1,1]
for r in range(21, 26):
    output[r] = [1,1,4,1,1,1,1,4,1,1,1,1]
output[26] = [1,1,1,1,4,4,4,4,1,1,1,1]

# Strategy: find leftmost and rightmost cols of 4s in each row,
# fill all columns between them with 2

for r in range(20, 27):
    # Find first 4
    first4 = None
    for c in range(12):
        if output[r][c] == 4:
            first4 = c
            break

    # Find last 4
    last4 = None
    for c in range(11, -1, -1):
        if output[r][c] == 4:
            last4 = c
            break

    if first4 is not None and last4 is not None and first4 < last4:
        # Fill between (exclusive of boundary cols)
        for c in range(first4 + 1, last4):
            if output[r][c] == 1:
                output[r][c] = 2

print("Between all 4s in each row:")
for r in range(20, 27):
    print(f"Row {r}: {output[r]}")

print(json.dumps({"action": "submit", "grid": output}))

